import React, { useEffect, useRef, memo } from 'react';

const TickerTape = () => {
  const containerRef = useRef();

  useEffect(() => {
    if (containerRef.current) {
        // Clear any old widgets to prevent duplicates
        containerRef.current.innerHTML = '';

        const script = document.createElement('script');
        script.src = 'https://s3.tradingview.com/external-embedding/embed-widget-ticker-tape.js';
        script.type = 'text/javascript';
        script.async = true;

        // Configuration for the scrolling ticker
        script.innerHTML = JSON.stringify({
          "symbols": [
            {
              "proName": "BSE:SENSEX",
              "title": "BSE Sensex"
            },
            {
              "proName": "BSE:BANKEX",
              "title": "Bank Nifty (BSE)"
            },
            {
              "proName": "TVC:GOLD",
              "title": "Gold"
            },
            {
              "proName": "TVC:USOIL",
              "title": "Crude Oil"
            }
          ],
          "showSymbolLogo": true,
          "isTransparent": false,
          "displayMode": "regular",
          "colorTheme": "light",
          "locale": "in"
        });

        containerRef.current.appendChild(script);
    }
  }, []);

  return (
    // We add a wrapper to give it some breathing room at the bottom of your page
    <div style={{ width: '100%', margin: '40px 0 20px 0', borderTop: '2px solid var(--accent-teal)' }}>
      <div className="tradingview-widget-container" ref={containerRef}>
        <div className="tradingview-widget-container__widget"></div>
      </div>
    </div>
  );
};

export default memo(TickerTape);
